import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';

describe('afterModelResponse usage [specs/hal-engine-config-hooks/spec.md#9]', () => {
  it('sums usage from a tool call and its final response', async () => {
    let calls = 0;
    const provider: AIProvider = {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        if (calls++ === 0) {
          yield {type: 'tool_use', toolCall: {id: 'one', name: 'lookup', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 2, outputTokens: 1, totalTokens: 3}};
        } else {
          yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 7, outputTokens: 4, totalTokens: 11}};
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'Look up a value', inputSchema: {type: 'object'}}, async () => 'found');
    let reported: UsageMetadata | undefined;
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test assistant'}), registry, {
      hooks: {afterModelResponse: async (_session, _text, usage) => void (reported = usage)},
    });

    await orchestrator.processMessage({
      sessionId: 'one',
      userId: 'user',
      entries: [{role: 'user', content: 'Look up a value', timestamp: '2026-01-01T00:00:00.000Z'}],
    });
    expect(reported).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });
});
EOF
